param([string]$RepoRoot='C:\Users\aaron\Desktop\URAP',[string]$RunId='vatd_rank_inputs_v1')
$root=Join-Path $RepoRoot 'artifacts\detached_vatd_rank_download';$pidFile=Join-Path $root ($RunId+'.pid');$metaFile=Join-Path $root ($RunId+'.meta.json')
$pidValue=if(Test-Path $pidFile){[int](Get-Content $pidFile|Select-Object -First 1)}else{0};$process=if($pidValue){Get-Process -Id $pidValue -ErrorAction SilentlyContinue}else{$null};$meta=if(Test-Path $metaFile){Get-Content $metaFile -Raw|ConvertFrom-Json}else{$null};$progress=if($meta -and (Test-Path $meta.progress)){Get-Content $meta.progress -Raw|ConvertFrom-Json}else{$null}
[ordered]@{running=[bool]$process;pid=$pidValue;start_time=if($process){$process.StartTime}else{$null};done=if($progress){$progress.done}else{0};total=if($progress){$progress.total}else{4};stage=if($progress){$progress.stage}else{'launch'};current=if($progress){$progress.remote}else{$null};last_output_timestamp=if($meta -and (Test-Path $meta.stdout)){(Get-Item $meta.stdout).LastWriteTime}else{$null};stdout=if($meta){$meta.stdout}else{$null};stderr=if($meta){$meta.stderr}else{$null}}|ConvertTo-Json -Depth 5
